INSERT INTO `course_lessons` (`id`, `course_id`, `module_id`, `title`, `slug`, `lesson_type`, `duration_label`, `video_url`, `cover_image`, `media_image`, `media_position`, `content_html`, `sort_order`, `is_preview`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 'Preparing for Salah: Purification (Taharah)', 'iera-my-prayer-series-pre-requisites-purification', 'youtube', '15 minutes', 'https://www.youtube.com/watch?v=33qU23CzfRo', 'uploads/course-covers/course_20260713_154259_7808184e1b0f.jpg', NULL, 'top', 'Before a Muslim stands before Allah in prayer, they must be in a state of purity. This lesson explains the importance of cleanliness in Islam, when Wudu or Ghusl is required, and the situations that invalidate Wudu.<div><br></div><div><p data-start=\"1008\" data-end=\"1029\" class=\"PDq2pG_selectionAnchorContainer\"><strong data-start=\"1008\" data-end=\"1029\">What you\'ll learn</strong><span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\n<ul data-start=\"1031\" data-end=\"1154\">\n<li data-section-id=\"14jnq2a\" data-start=\"1031\" data-end=\"1054\">\nImportance of Taharah\n</li>\n<li data-section-id=\"hnehie\" data-start=\"1055\" data-end=\"1080\">\nConditions before Salah\n</li>\n<li data-section-id=\"1i725h8\" data-start=\"1081\" data-end=\"1104\">\nWhen Wudu is required\n</li>\n<li data-section-id=\"7vullp\" data-start=\"1105\" data-end=\"1123\">\nWhat breaks Wudu\n</li>\n<li data-section-id=\"iup0yp\" data-start=\"1124\" data-end=\"1154\">\nWhy cleanliness is essential</li></ul></div>', 1, 0, '2026-07-13 15:39:26', '2026-07-13 15:42:59'),
(2, 1, 1, 'The Importance and Conditions of Salah', 'step-by-step-salah-tutorial-commonly-recommended-for-beginners', 'youtube', '15 minutes', 'https://www.youtube.com/watch?v=WKblG-Zoagk', NULL, NULL, 'top', '<p data-start=\"1413\" data-end=\"1617\" class=\"PDq2pG_selectionAnchorContainer\">Salah is the second pillar of Islam and one of the greatest acts of worship. This lesson explains why Muslims pray, the five daily prayers, and the conditions that must be fulfilled before Salah is valid.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\n<p data-start=\"1619\" data-end=\"1640\"><strong data-start=\"1619\" data-end=\"1640\">What you\'ll learn</strong></p>\n<ul data-start=\"1642\" data-end=\"1768\">\n<li data-section-id=\"ersa91\" data-start=\"1642\" data-end=\"1666\">\nWhy Salah is important\n</li>\n<li data-section-id=\"1rwhaei\" data-start=\"1667\" data-end=\"1691\">\nThe five daily prayers\n</li>\n<li data-section-id=\"1buczka\" data-start=\"1692\" data-end=\"1711\">\nFacing the Qiblah\n</li>\n<li data-section-id=\"1rql7yp\" data-start=\"1712\" data-end=\"1732\">\nCovering the Awrah\n</li>\n<li data-section-id=\"1bn485f\" data-start=\"1733\" data-end=\"1747\">\nPrayer times\n</li>\n<li data-section-id=\"5zlen7\" data-start=\"1748\" data-end=\"1768\">\nIntention (Niyyah)</li></ul>', 2, 0, '2026-07-13 15:39:26', '2026-07-13 15:42:59'),
(3, 1, 1, 'How to Perform Salah Step by Step', 'comprehensive-demonstration-of-the-daily-prayers', 'youtube', '15 Minutes', 'https://www.youtube.com/watch?v=W9kTd7q1zjE', NULL, NULL, 'top', '<p data-start=\"2008\" data-end=\"2205\" class=\"PDq2pG_selectionAnchorContainer\">This lesson demonstrates the complete prayer from Takbiratul Ihram to Tasleem. It explains each posture and recitation in sequence, helping learners become familiar with the correct order of Salah.<span aria-hidden=\"true\" class=\"PDq2pG_selectionAnchor\"></span></p>\n<p data-start=\"2207\" data-end=\"2228\"><strong data-start=\"2207\" data-end=\"2228\">What you\'ll learn</strong></p>\n<ul data-start=\"2230\" data-end=\"2356\">\n<li data-section-id=\"13pn3j0\" data-start=\"2230\" data-end=\"2248\">\nTakbiratul Ihram\n</li>\n<li data-section-id=\"op5ibs\" data-start=\"2249\" data-end=\"2267\">\nStanding (Qiyam)\n</li>\n<li data-section-id=\"duh0i5\" data-start=\"2268\" data-end=\"2284\">\nBowing (Ruku\')\n</li>\n<li data-section-id=\"1swa3pg\" data-start=\"2285\" data-end=\"2307\">\nProstration (Sujood)\n</li>\n<li data-section-id=\"1k16anq\" data-start=\"2308\" data-end=\"2319\">\nTashahhud\n</li>\n<li data-section-id=\"1cbdujz\" data-start=\"2320\" data-end=\"2329\">\nTasleem\n</li>\n<li data-section-id=\"amw4xg\" data-start=\"2330\" data-end=\"2356\">\nCommon mistakes to avoid</li></ul>', 3, 0, '2026-07-13 15:39:26', '2026-07-13 15:42:59');
