INSERT INTO `course_modules` (`id`, `course_id`, `title`, `slug`, `description`, `sort_order`, `created_at`, `updated_at`) VALUES
(1, 1, 'Introduction', 'my-prayer', 'My Prayer is narrated by Shaykh Bilal Dannoun, guiding you through the actions of purification and performing prayer in a simple and easy to understand manner. Through this series, you\'ll gain a complete overview of what is required to perform your prayers in the best and correct manner.', 1, '2026-07-13 15:39:26', '2026-07-13 15:42:59');
